// @vitest-environment jsdom

import { afterEach, expect, test, vi } from "vitest"
import { cleanup, render, screen } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import "@testing-library/jest-dom/vitest"

import { ButtonPlus } from "./button-plus"

afterEach(() => {
  cleanup()
})

test("loading 挡住点击并设置 aria-busy", async () => {
  const user = userEvent.setup()
  const onClick = vi.fn()
  render(
    <ButtonPlus loading onClick={onClick}>
      保存
    </ButtonPlus>,
  )

  const button = screen.getByRole("button", { name: "保存" })
  expect(button).toHaveAttribute("aria-busy", "true")
  await user.click(button)
  expect(onClick).not.toHaveBeenCalled()
})

test("htmlType 默认不提交表单，submit 会提交", async () => {
  const user = userEvent.setup()
  const onSubmit = vi.fn((event: SubmitEvent) => event.preventDefault())
  const { rerender } = render(
    <form
      onSubmit={(event) => {
        onSubmit(event.nativeEvent)
      }}
    >
      <ButtonPlus>保存</ButtonPlus>
    </form>,
  )

  await user.click(screen.getByRole("button", { name: "保存" }))
  expect(onSubmit).not.toHaveBeenCalled()

  rerender(
    <form
      onSubmit={(event) => {
        onSubmit(event.nativeEvent)
      }}
    >
      <ButtonPlus htmlType="submit">提交</ButtonPlus>
    </form>,
  )
  await user.click(screen.getByRole("button", { name: "提交" }))
  expect(onSubmit).toHaveBeenCalledTimes(1)
})

test("只有图标时，aria-label 就是按钮的名字", () => {
  render(<ButtonPlus icon={<span aria-hidden>★</span>} aria-label="编辑" />)
  expect(screen.getByRole("button", { name: "编辑" })).toBeInTheDocument()
})

test("id 和 aria-describedby 落在按钮上", () => {
  render(
    <ButtonPlus id="save" aria-describedby="save-hint">
      保存
    </ButtonPlus>,
  )
  const button = screen.getByRole("button", { name: "保存" })
  expect(button).toHaveAttribute("id", "save")
  expect(button).toHaveAttribute("aria-describedby", "save-hint")
})

import * as React from "react"
import { Loader2Icon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

type ButtonProps = React.ComponentProps<typeof Button>

export interface ButtonPlusProps extends Omit<ButtonProps, "type"> {
  loading?: boolean
  icon?: React.ReactNode
  danger?: boolean
  block?: boolean
  htmlType?: "button" | "submit" | "reset"
}

function hasLabel(children: React.ReactNode): boolean {
  return React.Children.count(children) > 0
}

function ButtonPlus({
  loading = false,
  icon,
  danger = false,
  block = false,
  htmlType = "button",
  variant,
  size,
  asChild = false,
  disabled,
  className,
  children,
  onClick,
  ...props
}: ButtonPlusProps) {
  const iconOnly = !hasLabel(children)
  const solidDanger = danger && (variant === undefined || variant === "default" || variant === "secondary")
  const resolvedVariant = solidDanger ? "destructive" : variant
  const dangerClass =
    danger && variant === "outline"
      ? "border-destructive text-destructive hover:bg-destructive/10 hover:text-destructive"
      : danger && variant === "ghost"
        ? "text-destructive hover:bg-destructive/10 hover:text-destructive"
        : danger && variant === "link"
          ? "text-destructive"
          : undefined
  const square = iconOnly && !asChild
  const buttonSize = square && (size === undefined || size === "default") ? "icon" : size

  return (
    <Button
      {...props}
      type={htmlType}
      variant={resolvedVariant}
      size={buttonSize}
      asChild={asChild}
      disabled={disabled || loading}
      aria-busy={loading ? true : props["aria-busy"]}
      data-danger={danger ? "true" : undefined}
      data-loading={loading ? "true" : undefined}
      data-block={block ? "true" : undefined}
      data-icon-only={square ? "true" : undefined}
      className={cn(
        "relative",
        dangerClass,
        block && "w-full",
        square && size === "sm" && "size-8",
        square && size === "lg" && "size-10",
        className,
      )}
      onClick={(event) => {
        if (loading) {
          event.preventDefault()
          return
        }
        onClick?.(event)
      }}
    >
      {asChild ? (
        children
      ) : (
        <>
          <span
            aria-hidden={loading || undefined}
            className={cn("inline-flex items-center justify-center gap-2", loading && "invisible")}
          >
            {icon}
            {children}
          </span>
          {loading ? (
            <span className="absolute inset-0 inline-flex items-center justify-center gap-2">
              <Loader2Icon className="size-4 animate-spin" aria-hidden />
              {children}
            </span>
          ) : null}
        </>
      )}
    </Button>
  )
}

export { ButtonPlus }

